class Solution {
public:
    int start = 0, best = 0;
    void expand(string& s, int l, int r) {
        while (l >= 0 && r < (int)s.size() && s[l] == s[r]) {
            l--;
            r++;
        }
        if (r - l - 1 > best) {
            best = r - l - 1;
            start = l + 1;
        }
    }
    string longestPalindrome(string s) {
        for (int c = 0; c < (int)s.size(); c++) {
            expand(s, c, c);
            expand(s, c, c + 1);
        }
        return s.substr(start, best);
    }
};
